}

export async function decideExecutionRule(inputs: ExecutionInputs): Promise<ExecutionRule> {
  const doctrine = { path: inputs.sec3.path, sha256: inputs.sec3.sha256 };
  const sec3 = (reasons: readonly string[]): ExecutionRule => ({ arm: 'sec-3', cites: 'SEC-3', doctrine, sec3Head: inputs.sec3.head, notPermittedBecause: reasons });
  if (inputs.role !== 'authoring') return sec3([`only the authoring session's brief may carry the permission; this is the ${inputs.role} brief`]);
  if (!inputs.permitting.enabled) return sec3([PERMITTING_ARM_DISABLED_REASON]);
  const { choices, probe } = inputs.permitting;
  if (choices === undefined || probe === undefined) return sec3(['the permitting arm is enabled without its choice source or credential probe']);

  const reasons: string[] = [];
  const launched = inputs.launched();
  if (launched === 'launched') reasons.push('this run was launched by `syzygy polaris`, and Syzygy never gives the execution instruction to a session it started');
  if (launched === 'unreadable') reasons.push('the run\'s launched marker is present but cannot be read as the one `syzygy polaris` writes, so the run is treated as launched');
  const d9 = await inputs.d9();
  if (d9.state !== 'ok') reasons.push(`D9 is not established in force: ${d9.why}`);
  if (inputs.sec3.cost === null) reasons.push(`SEC-3 in ${inputs.sec3.path} carries no cost bullet for the permitted case, so the cost cannot be quoted`);
  if (inputs.operatorIsOwner !== true) reasons.push('the run configuration does not declare the operator to be the owner');
  const found = await choices.choiceFor(inputs.runDir);
  let choice: ExecutionChoice | null = null;
  if (found.state !== 'ok') {
    reasons.push(`no execution choice is recorded for this run by allow-execution: ${found.why}`);
  } else {
    choice = found.choice;
    if (choice.command !== 'allow-execution') reasons.push(`the execution choice ${choice.recordId} was not recorded by allow-execution`);
    if (choice.runId !== inputs.runId) reasons.push(`the execution choice ${choice.recordId} names run ${choice.runId}, not ${inputs.runId}`);
    if (choice.revision !== inputs.pinnedRevision) reasons.push(`the execution choice ${choice.recordId} names revision ${choice.revision}, not the pinned ${inputs.pinnedRevision}`);
    const at = Date.parse(choice.recordedAt);
    if (!/^\d{4}-\d{2}-\d{2}T/.test(choice.recordedAt) || Number.isNaN(at)) reasons.push(`the execution choice ${choice.recordId} carries no readable instant`);
    else if (at > inputs.now) reasons.push(`the execution choice ${choice.recordId} is dated after the brief`);
    const declared = choice.declarations;
    if (declared.ownerStartedSession !== true) reasons.push('the operator has not declared that the owner started the authoring session');
    if (declared.ownersOwnHost !== true) reasons.push('the operator has not declared that the authoring session runs on the owner\'s own host');
    if (declared.ownerAttends !== true) reasons.push('the operator has not declared that the owner attends the authoring session');
  }
  const probed = await probe.probe();
  if (!probed.passed) reasons.push(`the adapter-credential probe did not pass: ${probed.why}`);

  if (reasons.length > 0 || d9.state !== 'ok' || choice === null || !probed.passed || inputs.sec3.cost === null) return sec3(reasons);
  return { arm: 'permitting', cites: 'SEC-3 (D9)', doctrine, d9: d9.record, choice, choiceLabel: 'Inferred', probe: { checked: probed.checked, source: probed.source }, cost: inputs.sec3.cost };
}

function stop(options: Options): number {
  const state = readState(options.stateRoot, options.run!);
  if (state === null) return refuse(`no launched run ${options.run} under ${options.stateRoot}`);
  if (tmuxHas(state.tmuxSession)) spawnSync('tmux', ['kill-session', '-t', state.tmuxSession], { stdio: 'ignore' });
  state.stopped ??= new Date().toISOString();
  saveState(options.stateRoot, state);
  process.stdout.write(`Stopped run ${state.runId}; every session it started has ended.\n  resume: syzygy polaris --resume ${state.runId}\n`);
  return 0;
}

function readSubject(value: unknown): RunSubject | string {
  if (!isRecord(value) || !hasKeys(value, ['repository', 'clone', 'pinnedRevision', 'startGates', 'governed', 'providerStatement', 'workItem'])) return 'it must carry exactly repository, clone, pinnedRevision, startGates, governed, providerStatement and workItem';
  const { repository, clone, pinnedRevision, startGates, governed, providerStatement, workItem } = value;
  if (!isRecord(repository) || !hasKeys(repository, ['url', 'repositoryId']) || !isText(repository['url']) || !isText(repository['repositoryId'])) return 'repository must carry a url and a repositoryId';
  const url = dossierRepositoryUrl(repository['url']);
  if (!url.ok || url.url !== repository['url'] || !/^[a-z0-9][a-z0-9-]*$/.test(repository['repositoryId'])) return 'repository url or repositoryId is malformed';
  if (!isRecord(clone) || !hasKeys(clone, ['path', 'declaredBy', 'label', 'use']) || clone['declaredBy'] !== 'operator' || clone['label'] !== 'Inferred' || clone['use'] !== 'read') return 'clone must carry its path, declared by the operator, labelled Inferred, for reading only';
  if (typeof clone['path'] !== 'string' || clone['path'].length > 4096 || path.resolve(clone['path']) !== clone['path'] || clone['path'].includes('\0')) return 'the clone path is not an absolute, normalised path';
  if (!isRecord(pinnedRevision) || !hasKeys(pinnedRevision, ['commit', 'label', 'consentRecord', 'pinnedAt'])) return 'pinnedRevision must carry commit, label, consentRecord and pinnedAt';
  if (typeof pinnedRevision['commit'] !== 'string' || !/^(?:[0-9a-f]{40}|[0-9a-f]{64})$/.test(pinnedRevision['commit'])) return 'the pinned commit is not a full commit identifier';
  if (!isText(pinnedRevision['label']) || !isText(pinnedRevision['consentRecord'])) return 'the pinned revision must name its label and consent record';
  if (typeof pinnedRevision['pinnedAt'] !== 'string' || !INSTANT.test(pinnedRevision['pinnedAt']) || Number.isNaN(Date.parse(pinnedRevision['pinnedAt']))) return 'pinnedAt is not a UTC instant';
  if (!isRecord(startGates) || !hasKeys(startGates, ['registryEntry', 'screeningPolicy']) || !isText(startGates['registryEntry']) || !isText(startGates['screeningPolicy'])) return 'startGates must cite the registry entry and screening policy records';
  if (!isRecord(governed) || !hasKeys(governed, ['kind', 'because']) || !GOVERNED_KINDS.includes(governed['kind'] as GovernedKind)
    || !Array.isArray(governed['because']) || governed['because'].length === 0 || !governed['because'].every(isText)) return 'governed must carry a kind and its reasons';
  const kind = governed['kind'] as GovernedKind;
  if (providerStatement !== null && !isText(providerStatement)) return 'providerStatement must be a record citation or null';
  if (kind !== 'non-governed' && providerStatement === null) return `${kind === 'unstated' ? 'an unstated' : 'a governed'} subject must cite the per-project statement it relies on`;
  if (!isRecord(workItem) || !hasKeys(workItem, ['identity', 'reason']) || workItem['identity'] !== null || workItem['reason'] !== NO_WORK_ITEM_REASON) return 'workItem must record an absent identity with its reason';
  return {
    repository: { url: repository['url'], repositoryId: repository['repositoryId'] },
    clone: { path: clone['path'], declaredBy: 'operator', label: 'Inferred', use: 'read' },
    pinnedRevision: { commit: pinnedRevision['commit'], label: pinnedRevision['label'], consentRecord: pinnedRevision['consentRecord'], pinnedAt: pinnedRevision['pinnedAt'] },
    startGates: { registryEntry: startGates['registryEntry'], screeningPolicy: startGates['screeningPolicy'] },
    governed: { kind, because: [...(governed['because'] as string[])] },
    providerStatement: providerStatement as string | null,
    workItem: { identity: null, reason: NO_WORK_ITEM_REASON },
  };
}

